653: /* returns WS_SUCCESS on success */
654: static INLINE int HighwaterCheck(WOLFSSH* ssh, byte side)
655: {
656:     int ret = WS_SUCCESS;
657:     int fire = 0;
658: 
659:     /* RFC 4253 Sec 9: bound bytes per key (txCount/rxCount reset on rekey)
660:      * to limit cipher keystream/IV exhaustion under a single key. */
661:     if (!ssh->highwaterFlag && ssh->highwaterMark &&
662:         (ssh->txCount >= ssh->highwaterMark ||
663:          ssh->rxCount >= ssh->highwaterMark)) {
664: 
665:         WLOG(WS_LOG_DEBUG, "%s over high water mark",
666:              (side == WOLFSSH_HWSIDE_TRANSMIT) ? "Transmit" : "Receive");
667: 
668:         ssh->highwaterFlag = 1;
669:         fire = 1;
670:     }
671: 
672:     /* RFC 4344 Sec 3.1: rekey before the 32-bit SSH sequence number wraps
673:      * to prevent MAC/nonce reuse. Counter is per-key (resets on rekey),
674:      * not the absolute ssh->seq (which resets only at a strict KEX
675:      * NEWKEYS); default 2^31 keeps each epoch comfortably under the
676:      * 2^32 wrap. */
677:     if (!ssh->msgHighwaterFlag && ssh->msgHighwaterMark &&
678:         (ssh->txMsgCount >= ssh->msgHighwaterMark ||
679:          ssh->rxMsgCount >= ssh->msgHighwaterMark)) {
680: 
681:         WLOG(WS_LOG_DEBUG, "%s over msg high water mark",
682:              (side == WOLFSSH_HWSIDE_TRANSMIT) ? "Transmit" : "Receive");
683: 
684:         ssh->msgHighwaterFlag = 1;
685:         fire = 1;
686:     }
687: 
688: 
689:     /* A mark firing on a dead session must not fail the send that fired it:
690:      * this return propagates out of wolfSSH_SendPacket(). Callbacks rekey,
691:      * which is gated after a disconnect, so do not fire one at all. */
692:     if (fire && ssh->disconnected)
693:         fire = 0;
694: 
695:     if (fire && ssh->ctx->highwaterCb)
696:         ret = ssh->ctx->highwaterCb(side, ssh->highwaterCtx);
697: 
698:     return ret;
699: }
