707:     newHs = (HandshakeInfo*)WMALLOC(sizeof(HandshakeInfo),
708:                                     heap, DYNTYPE_HS);
709:     if (newHs != NULL) {
710:         WMEMSET(newHs, 0, sizeof(HandshakeInfo));
711:         newHs->kexHashId = WC_HASH_TYPE_NONE;
712:         newHs->blockSz = MIN_BLOCK_SZ;
713:         newHs->peerBlockSz = MIN_BLOCK_SZ;
714:         /* peerEncryptId, peerMacId, peerAeadMode, peerMacSz: left at 0
715:          * (== ID_NONE / no-MAC) by the WMEMSET above. */
716:         newHs->eSz = (word32)sizeof(newHs->e);
717:         newHs->xSz = (word32)sizeof(newHs->x);
718: #ifndef WOLFSSH_NO_DH_GEX_SHA256
719:         newHs->dhGexMinSz = WOLFSSH_DEFAULT_GEXDH_MIN;
720:         newHs->dhGexPreferredSz = WOLFSSH_DEFAULT_GEXDH_PREFERRED;
721:         newHs->dhGexMaxSz = WOLFSSH_DEFAULT_GEXDH_MAX;
722: #endif
723:     }
724: 
725:     return newHs;
726: }
