729: static void HandshakeInfoFree(HandshakeInfo* hs, void* heap)
730: {
731:     WOLFSSH_UNUSED(heap);
732: 
733:     WLOG(WS_LOG_DEBUG, "Entering HandshakeInfoFree()");
734:     if (hs) {
735:         WFREE(hs->kexInit, heap, DYNTYPE_STRING);
736: #ifndef WOLFSSH_NO_DH
737:         WFREE(hs->primeGroup, heap, DYNTYPE_MPINT);
738:         WFREE(hs->generator, heap, DYNTYPE_MPINT);
739:         if (hs->useDh) {
740:             wc_FreeDhKey(&hs->privKey.dh);
741:         }
742: #endif
743: #ifndef WOLFSSH_NO_ECDH
744:         /* privKey is a union; the Curve25519+ML-KEM hybrid sets both
745:          * useMlKem and useCurve25519 but generates a curve25519 key, which is
746:          * freed below. The NIST ECC hybrid sets useEcdh, so useEcdh alone
747:          * covers every case that generates an ecc key. */
748:         if (hs->useEcdh) {
749:             wc_ecc_free(&hs->privKey.ecc);
750:         }
751: #endif
752: #if !defined(WOLFSSH_NO_CURVE25519_SHA256) || \
753:     !defined(WOLFSSH_NO_CURVE25519_MLKEM768_SHA256)
754:         if (hs->useCurve25519) {
755:             wc_curve25519_free(&hs->privKey.curve25519);
756:         }
757: #endif
758:         if (hs->kexHashId != WC_HASH_TYPE_NONE)  {
759:             wc_HashFree(&hs->kexHash, (enum wc_HashType)hs->kexHashId);
760:         }
761:         WS_FORCEZERO(hs, sizeof(HandshakeInfo));
762:         WFREE(hs, heap, DYNTYPE_HS);
763:     }
764: }
