767: #ifndef NO_WOLFSSH_SERVER
768: INLINE static int IsMessageAllowedServer(WOLFSSH *ssh, byte msg)
769: {
770:     /* Only the server should send these messages, never receive. */
771:     if (msg == MSGID_SERVICE_ACCEPT ||
772:             msg == MSGID_KEXDH_REPLY || /* 31: also ECDH, KEM, GEX_GROUP */
773:             msg == MSGID_KEXDH_GEX_REPLY) {
774:         WLOG(WS_LOG_DEBUG, "Message ID %u not allowed by %s %s",
775:                 msg, "server", "ever");
776:         ssh->error = WS_MSGID_NOT_ALLOWED_E;
777:         return 0;
778:     }
779: 
780:     if (msg == MSGID_SERVICE_REQUEST) {
781:         /* RFC 4253 section 7.1: no service request once the peer's KEXINIT
782:          * lands. acceptState doesn't track a rekey. */
783:         if (ssh->isKeying & WOLFSSH_PEER_IS_KEYING) {
784:             WLOG(WS_LOG_DEBUG, "Message ID %u not allowed by %s %s",
785:                     msg, "server", "when keying");
786:             ssh->error = WS_MSGID_NOT_ALLOWED_E;
787:             return 0;
788:         }
789: 
790:         if (ssh->acceptState == ACCEPT_KEYED) {
791:             return 1;
792:         }
793:         else {
794:             WLOG(WS_LOG_DEBUG, "Message ID %u not allowed by %s %s",
795:                     msg, "server", "after starting user auth");
796:             return 0;
797:         }
798:     }
799: 
800:     /* Transport Layer Generic messages are always allowed. */
801:     if (MSGIDLIMIT_TRANS_GEN(msg)) {
802:         return 1;
803:     }
804: 
805:     /* Is KEX complete? */
806:     if (MSGIDLIMIT_TRANS(msg)) {
807:         if (ssh->isKeying & WOLFSSH_PEER_IS_KEYING) {
808:             /* MSGID_KEXINIT not allowed when keying. */
809:             if (msg == MSGID_KEXINIT) {
810:                 WLOG(WS_LOG_DEBUG, "Message ID %u not allowed by %s %s",
811:                         msg, "server", "when keying");
812:                 ssh->error = WS_MSGID_NOT_ALLOWED_E;
813:                 return 0;
814:             }
815: 
816:             /* Error if expecting a specific message and didn't receive. */
817:             if (ssh->handshake && ssh->handshake->expectMsgId != MSGID_NONE) {
818:                 /* The explicit expectMsgId check supersedes the old
819:                  * IsMessageAllowedKeying() stub for rekey filtering. */
820:                 if (msg != ssh->handshake->expectMsgId) {
821:                     WLOG(WS_LOG_DEBUG,
822:                             "Message ID %u not the expected message %u",
823:                             msg, ssh->handshake->expectMsgId);
824:                     ssh->error = WS_MSGID_NOT_ALLOWED_E;
825:                     return 0;
826:                 }
827:                 else {
828:                     /* Got the expected message, clear expectation. */
829:                     ssh->handshake->expectMsgId = MSGID_NONE;
830:                     return 1;
831:                 }
832:             }
833:         }
834:         else {
835:             /* MSGID_KEXINIT only allowed when not keying. */
836:             if (msg == MSGID_KEXINIT) {
837:                 return 1;
838:             }
839: 
840:             /* All other transport KEX and ALGO messages are not allowed
841:              * when not keying. */
842:             WLOG(WS_LOG_DEBUG, "Message ID %u not allowed by %s %s",
843:                     msg, "server", "when not keying");
844:             ssh->error = WS_MSGID_NOT_ALLOWED_E;
845:             return 0;
846:         }
847:     }
848: 
849:     /* Has client userauth started? */
850:     /* Allows the server to receive up to KEXDH GEX Request during KEX. */
851:     if (ssh->acceptState < ACCEPT_KEYED) {
852:         if (msg > MSGID_KEXDH_GEX_REQUEST) {
853:             return 0;
854:         }
855:     }
856: 
857:     /* Is server userauth complete? */
858:     if (ssh->acceptState < ACCEPT_SERVER_USERAUTH_SENT) {
859:         /* The server should only receive the user auth request message,
860:          * it should not accept the other user auth messages, it sends
861:          * them. (>50) */
862:         /* Explicitly check for messages not allowed before user
863:          * authentication has completed. */
864:         if (MSGIDLIMIT_POST_USERAUTH(msg)) {
865:             WLOG(WS_LOG_DEBUG, "Message ID %u not allowed by %s %s",
866:                     msg, "server", "before user authentication is complete");
867:             return 0;
868:         }
869:         /* Explicitly check for the user authentication messages that
870:          * only the server sends, it shouldn't receive them. */
871:         if ((msg > MSGID_USERAUTH_REQUEST) &&
872:             (msg != MSGID_USERAUTH_INFO_RESPONSE)) {
873:             WLOG(WS_LOG_DEBUG, "Message ID %u not allowed by %s %s",
874:                     msg, "server", "during user authentication");
875:             return 0;
876:         }
877:     }
878:     else {
879:         if (msg >= MSGID_USERAUTH_REQUEST && msg < MSGID_GLOBAL_REQUEST) {
880:             WLOG(WS_LOG_DEBUG, "Message ID %u not allowed by %s %s",
881:                     msg, "server", "after user authentication");
882:             return 0;
883:         }
884:     }
885: 
886:     return 1;
887: }
888: #endif /* NO_WOLFSSH_SERVER */
