13973: static int DoPacket(WOLFSSH* ssh, byte* bufferConsumed)
13974: {
13975:     byte* buf = (byte*)ssh->inputBuffer.buffer;
13976:     word32 pktStart = ssh->inputBuffer.idx;
13977:     word32 pktSz = ssh->curSz;
13978:     word32 idx = pktStart;
13979:     word32 len = ssh->inputBuffer.length;
13980:     word32 payloadSz;
13981:     byte padSz;
13982:     byte msg;
13983:     word32 payloadIdx = 0;
13984:     int msgAllowed;
13985:     byte newKeysDone = 0;
13986:     int ret = WS_SUCCESS;
13987: 
13988:     WLOG(WS_LOG_DEBUG, "DoPacket sequence number: %d", ssh->peerSeq);
13989: 
13990:     *bufferConsumed = 0;
13991: 
13992:     idx += UINT32_SZ;
13993:     padSz = buf[idx++];
13994: 
13995:     /* RFC 4253 section 6 requires at least four bytes of padding. */
13996:     if (padSz < MIN_PAD_LENGTH) {
13997:         WLOG(WS_LOG_DEBUG, "Packet padding length %u below minimum %u",
13998:              (word32)padSz, (word32)MIN_PAD_LENGTH);
13999:         return WS_BUFFER_E;
14000:     }
14001: 
14002:     /* check for underflow */
14003:     if ((word32)(PAD_LENGTH_SZ + padSz + MSG_ID_SZ) > pktSz) {
14004:         return WS_OVERFLOW_E;
14005:     }
14006: 
14007:     payloadSz = pktSz - PAD_LENGTH_SZ - padSz - MSG_ID_SZ;
14008: 
14009:     msg = buf[idx++];
14010:     /* At this point, payload starts at "buf + idx". */
14011: 
14012:     /* sanity check on payloadSz. Uses "or" condition because of the case when
14013:      * adding idx to payloadSz causes it to overflow.
14014:      */
14015:     if ((ssh->inputBuffer.bufferSz < payloadSz + idx) ||
14016:             (payloadSz + idx < payloadSz)) {
14017:         return WS_OVERFLOW_E;
14018:     }
14019: 
14020:     msgAllowed = IsMessageAllowed(ssh, msg, WS_MSG_RECV);
14021: 
14022:     if (!msgAllowed && ssh->useStrictKex && !ssh->initialKexDone) {
14023:         /* Strict KEX calls for terminating the connection, not just
14024:          * dropping the packet, so tell the peer why on the way out. Every
14025:          * refused id ends it here, the unassigned ones an UNIMPLEMENTED
14026:          * would otherwise answer included. The error is relatched because
14027:          * the send path can overwrite it. */
14028:         if (!ssh->disconnected) {
14029:             (void)SendDisconnect(ssh,
14030:                     WOLFSSH_DISCONNECT_KEY_EXCHANGE_FAILED);
14031:             ssh->error = WS_MSGID_NOT_ALLOWED_E;
14032:         }
14033:         return WS_MSGID_NOT_ALLOWED_E;
14034:     }
14035: 
14036:     if (!msgAllowed && (MsgIdKnown(msg) || MSGIDLIMIT_POST_USERAUTH(msg))) {
14037:         /* RFC 4252 section 6: disconnect on a known id at the wrong time,
14038:          * and on any id of 80 or higher, which IsMessageAllowed() refuses
14039:          * only before auth. Silent once over, RFC 4253 section 11.1. */
14040:         if (!ssh->disconnected) {
14041:             (void)SendDisconnect(ssh, WOLFSSH_DISCONNECT_PROTOCOL_ERROR);
14042:         }
14043:         return WS_MSGID_NOT_ALLOWED_E;
14044:     }
14045: 
14046:     /* The session is over, RFC 4253 section 11.1, so skip the whole dispatch:
14047:      * the handlers that answer must not, and what the rest would record is of
14048:      * no use to a caller that can no longer send. Inbound data from here on is
14049:      * dropped rather than buffered. The frame advance at the end steps over
14050:      * the packet, so the stream stays in step. A DISCONNECT still dispatches,
14051:      * since DoDisconnect() sends nothing and latches the error. */
14052:     if (ssh->disconnected && msg != MSGID_DISCONNECT) {
14053:         WLOG(WS_LOG_DEBUG, "Ignoring message ID %u after a disconnect",
14054:              (word32)msg);
14055:     }
14056:     else if (!msgAllowed) {
14057:         /* Refused, unimplemented, below 80. Answered off the dispatch so a
14058:          * refused id cannot reach a handler if MsgIdKnown() drifts. */
14059:         WLOG(WS_LOG_DEBUG, "Unimplemented message ID (%d)", msg);
14060:         ret = SendUnimplemented(ssh);
14061:     }
14062:     else switch (msg) {
14063: 
14064:         case MSGID_DISCONNECT:
14065:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_DISCONNECT");
14066:             ret = DoDisconnect(ssh, buf + idx, payloadSz, &payloadIdx);
14067:             break;
14068: 
14069:         case MSGID_IGNORE:
14070:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_IGNORE");
14071:             ret = DoIgnore(ssh, buf + idx, payloadSz, &payloadIdx);
14072:             break;
14073: 
14074:         case MSGID_UNIMPLEMENTED:
14075:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_UNIMPLEMENTED");
14076:             ret = DoUnimplemented(ssh, buf + idx, payloadSz, &payloadIdx);
14077:             break;
14078: 
14079:         case MSGID_REQUEST_SUCCESS:
14080:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_REQUEST_SUCCESS");
14081:             ret = DoRequestSuccess(ssh, buf + idx, payloadSz, &payloadIdx);
14082:             break;
14083: 
14084:         case MSGID_REQUEST_FAILURE:
14085:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_REQUEST_FAILURE");
14086:             ret = DoRequestFailure(ssh, buf + idx, payloadSz, &payloadIdx);
14087:             break;
14088: 
14089:         case MSGID_DEBUG:
14090:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_DEBUG");
14091:             ret = DoDebug(ssh, buf + idx, payloadSz, &payloadIdx);
14092:             break;
14093: 
14094:         case MSGID_EXT_INFO:
14095:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_EXT_INFO");
14096:             ret = DoExtInfo(ssh, buf + idx, payloadSz, &payloadIdx);
14097:             break;
14098: 
14099:         case MSGID_KEXINIT:
14100:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_KEXINIT");
14101:             ret = DoKexInit(ssh, buf + idx, payloadSz, &payloadIdx);
14102:             /* Don't answer a KEXINIT that failed to negotiate; DoKexInit()
14103:              * has already disconnected. A healthy rekey lands here as
14104:              * WS_REKEYING, so this cannot test for WS_SUCCESS. */
14105:             if (!IsKexMatchError(ret) && ssh->isKeying &&
14106:                     ssh->connectState == CONNECT_SERVER_CHANNEL_REQUEST_DONE) {
14107:                 if (ssh->handshake->kexId == ID_DH_GEX_SHA256) {
14108: #if !defined(WOLFSSH_NO_DH) && !defined(WOLFSSH_NO_DH_GEX_SHA256)
14109:                     ssh->error = SendKexDhGexRequest(ssh);
14110: #endif
14111:                 }
14112:                 else
14113:                     ssh->error = SendKexDhInit(ssh);
14114:             }
14115:             break;
14116: 
14117:         case MSGID_NEWKEYS:
14118:         {
14119:             /* DoNewKeys() frees the handshake once the keys are in, even
14120:              * when the window flush after that wants a write. */
14121:             byte hadHandshake = (ssh->handshake != NULL);
14122: 
14123:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_NEWKEYS");
14124:             ret = DoNewKeys(ssh, buf + idx, payloadSz, &payloadIdx);
14125:             newKeysDone = hadHandshake && ssh->handshake == NULL;
14126:             break;
14127:         }
14128: 
14129:         case MSGID_KEXDH_INIT:
14130:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_KEXDH_INIT");
14131:             ret = DoKexDhInit(ssh, buf + idx, payloadSz, &payloadIdx);
14132:             break;
14133: 
14134:         case MSGID_KEXDH_REPLY:
14135:             if (ssh->handshake == NULL) {
14136:                 ret = WS_MEMORY_E;
14137:                 break;
14138:             }
14139: 
14140:             if (ssh->handshake->kexId == ID_DH_GEX_SHA256) {
14141: #ifndef WOLFSSH_NO_DH_GEX_SHA256
14142:                 WLOG(WS_LOG_DEBUG, "Decoding MSGID_KEXDH_GEX_GROUP");
14143:                 ret = DoKexDhGexGroup(ssh, buf + idx, payloadSz, &payloadIdx);
14144: #endif
14145:             }
14146:             else {
14147:                 WLOG(WS_LOG_DEBUG, "Decoding MSGID_KEXDH_REPLY");
14148:                 ret = DoKexDhReply(ssh, buf + idx, payloadSz, &payloadIdx);
14149:             }
14150:             break;
14151: 
14152: #ifndef WOLFSSH_NO_DH_GEX_SHA256
14153:         case MSGID_KEXDH_GEX_REQUEST:
14154:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_KEXDH_GEX_REQUEST");
14155:             ret = DoKexDhGexRequest(ssh, buf + idx, payloadSz, &payloadIdx);
14156:             break;
14157: #endif
14158: 
14159:         case MSGID_KEXDH_GEX_INIT:
14160:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_KEXDH_GEX_INIT");
14161:             ret = DoKexDhInit(ssh, buf + idx, payloadSz, &payloadIdx);
14162:             break;
14163: 
14164:         case MSGID_KEXDH_GEX_REPLY:
14165:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_KEXDH_GEX_INIT");
14166:             ret = DoKexDhReply(ssh, buf + idx, payloadSz, &payloadIdx);
14167:             break;
14168: 
14169:         case MSGID_SERVICE_REQUEST:
14170:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_SERVICE_REQUEST");
14171:             ret = DoServiceRequest(ssh, buf + idx, payloadSz, &payloadIdx);
14172:             break;
14173: 
14174:         case MSGID_SERVICE_ACCEPT:
14175:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_SERVER_ACCEPT");
14176:             ret = DoServiceAccept(ssh, buf + idx, payloadSz, &payloadIdx);
14177:             break;
14178: 
14179:         case MSGID_USERAUTH_REQUEST:
14180:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_USERAUTH_REQUEST");
14181:             ret = DoUserAuthRequest(ssh, buf + idx, payloadSz, &payloadIdx);
14182:             break;
14183: 
14184: #ifdef WOLFSSH_KEYBOARD_INTERACTIVE
14185:         case MSGID_USERAUTH_INFO_RESPONSE:
14186:             WLOG(WS_LOG_DEBUG, "Decoding MSG_USERAUTH_INFO_RESPONSE");
14187:             ret = DoUserAuthInfoResponse(ssh, buf + idx, payloadSz, &payloadIdx);
14188:             break;
14189: 
14190:         case MSGID_USERAUTH_INFO_REQUEST:
14191:             WLOG(WS_LOG_DEBUG, "Decoding MSGID_USERAUTH_INFO_REQUEST");
14192:             ret = DoUserAuthInfoRequest(ssh, buf + idx, payloadSz, &payloadIdx);
14193:             break;
14194: #endif
14195: 
18900:     return ret;
18901: }
