18904: int SendNewKeys(WOLFSSH* ssh)
18905: {
18906:     byte* output;
18907:     word32 idx = 0;
18908:     int ret = WS_SUCCESS;
18909:     int adjustResult;
18910: 
18911:     WLOG(WS_LOG_DEBUG, "Entering SendNewKeys()");
18912:     if (ssh == NULL)
18913:         ret = WS_BAD_ARGUMENT;
18914: 
18915:     if (ret == WS_SUCCESS)
18916:         ret = PreparePacket(ssh, MSG_ID_SZ);
18917: 
18918:     if (ret == WS_SUCCESS) {
18919:         output = ssh->outputBuffer.buffer;
18920:         idx = ssh->outputBuffer.length;
18921: 
18922:         output[idx++] = MSGID_NEWKEYS;
18923: 
18924:         ssh->outputBuffer.length = idx;
18925: 
18926:         ret = BundlePacket(ssh);
18927: 
18928:         /* Strict KEX (Terrapin mitigation): once negotiated, every
18929:          * SSH_MSG_NEWKEYS resets the outgoing sequence number so the next
18930:          * outbound packet starts at zero under the new keys. This has to
18931:          * happen here, before SendPendingChannelWindowAdjust() below can
18932:          * bundle a packet, or that packet goes out at the old sequence
18933:          * number while the peer MACs it at zero. */
18934:         if (ret == WS_SUCCESS && ssh->useStrictKex) {
18935:             ssh->seq = 0;
18936:         }
18937:     }
18938: 
18939:     if (ret == WS_SUCCESS) {
18940:         ssh->blockSz = ssh->handshake->blockSz;
18941:         ssh->encryptId = ssh->handshake->encryptId;
18942:         ssh->macSz = ssh->handshake->macSz;
18943:         ssh->macId = ssh->handshake->macId;
18944:         ssh->aeadMode = ssh->handshake->aeadMode;
18945:         WMEMCPY(&ssh->keys, &ssh->handshake->keys, sizeof(Keys));
18946: 
18947:         ret = CipherSetKey(&ssh->encryptCipher,
18948:                 ssh->encryptId, 1, ssh->keys.iv,
18949:                 ssh->keys.encKey, ssh->keys.encKeySz,
18950:                 ssh->ctx->heap);
18951:     }
18952: 
18953:     if (ret == WS_SUCCESS) {
18954:         ssh->txCount = 0;
18955:         ssh->txMsgCount = 0;
18956: 
18957:         ret = wolfSSH_SendPacket(ssh);
18958: 
18959:         /* Clear self is keying flag */
18960:         ssh->isKeying &= ~WOLFSSH_SELF_IS_KEYING;
18961: 
18962:         /* If this was the last keying flag to clear, flush any window credit
18963:          * that was deferred during the rekey (RFC 4253 section 7.1). Don't let
18964:          * it mask a send failure from above. */
18965:         adjustResult = SendPendingChannelWindowAdjust(ssh);
18966:         if (ret == WS_SUCCESS)
18967:             ret = adjustResult;
18968:     }
